135	// UpsertInstances inserts or overwrites several instances of one service in a
136	// single transaction. Every input shares the same service name and instance
137	// ids are expected to be unique within the batch; stored records are returned
138	// in request order. Any failure rolls the whole batch back without leaving
139	// partial updates.
140	func (s *Store) UpsertInstances(inputs []InstanceInput) ([]Instance, error) {
141		tx, err := s.db.Begin()
142		if err != nil {
143			return nil, err
144		}
145		defer tx.Rollback()
146	
147		statement, err := tx.Prepare(`
148	INSERT INTO service_instances
149		(service_name, instance_id, address, port, healthy, weight, heartbeat_at)
150	VALUES (?, ?, ?, ?, ?, ?, ?)
151	ON CONFLICT(service_name, instance_id) DO UPDATE SET
152		address = excluded.address,
153		port = excluded.port,
154		healthy = excluded.healthy,
155		weight = excluded.weight,
156		heartbeat_at = excluded.heartbeat_at`)
157		if err != nil {
158			return nil, err
159		}
160		defer statement.Close()
161	
162		for _, input := range inputs {
163			if _, err := statement.Exec(
164				input.ServiceName, input.InstanceID, input.Address, input.Port,
165				input.Healthy, input.Weight,
166				input.HeartbeatAt.UTC().Format(time.RFC3339Nano)); err != nil {
167				return nil, err
168			}
169		}
170	
171		instances := make([]Instance, 0, len(inputs))
172		for _, input := range inputs {
173			instances = append(instances, Instance{
174				ServiceName: input.ServiceName,
175				InstanceID:  input.InstanceID,
176				Address:     input.Address,
177				Port:        input.Port,
178				Healthy:     input.Healthy,
179				Weight:      input.Weight,
180				HeartbeatAt: input.HeartbeatAt.UTC(),
181			})
182		}
183	
184		if err := tx.Commit(); err != nil {
185			return nil, err
186		}
187		return instances, nil
188	}
