260	// DeleteInstance removes one instance record and reports whether it existed.
261	func (s *Store) DeleteInstance(serviceName, instanceID string) (bool, error) {
262		result, err := s.db.Exec(`
263	DELETE FROM service_instances WHERE service_name = ? AND instance_id = ?`, serviceName, instanceID)
264		if err != nil {
265			return false, err
266		}
267		affected, err := result.RowsAffected()
268		if err != nil {
269			return false, err
270		}
271		return affected > 0, nil
272	}
