280	// DeleteInstances removes the identified records in a single transaction.
281	// Any failure rolls the whole batch back, so a failed request never leaves
282	// partial deletions behind.
283	func (s *Store) DeleteInstances(keys []InstanceKey) error {
284		tx, err := s.db.Begin()
285		if err != nil {
286			return err
287		}
288		defer tx.Rollback()
289	
290		statement, err := tx.Prepare(`
291	DELETE FROM service_instances WHERE service_name = ? AND instance_id = ?`)
292		if err != nil {
293			return err
294		}
295		defer statement.Close()
296	
297		for _, key := range keys {
298			if _, err := statement.Exec(key.ServiceName, key.InstanceID); err != nil {
299				return err
300			}
301		}
302		return tx.Commit()
303	}
