305	// TouchHeartbeats replaces only heartbeat_at of the named service's
306	// instances. The whole batch runs in one transaction: when any target does
307	// not exist the transaction rolls back and ErrInstanceNotFound is returned
308	// without partial updates. Updated records are returned in request order.
309	func (s *Store) TouchHeartbeats(serviceName string, targets []HeartbeatTarget) ([]Instance, error) {
310		tx, err := s.db.Begin()
311		if err != nil {
312			return nil, err
313		}
314		defer tx.Rollback()
315	
316		statement, err := tx.Prepare(`
317	UPDATE service_instances SET heartbeat_at = ?
318	WHERE service_name = ? AND instance_id = ?`)
319		if err != nil {
320			return nil, err
321		}
322		defer statement.Close()
323	
324		for _, target := range targets {
325			result, err := statement.Exec(
326				target.HeartbeatAt.UTC().Format(time.RFC3339Nano), serviceName, target.InstanceID)
327			if err != nil {
328				return nil, err
329			}
330			affected, err := result.RowsAffected()
331			if err != nil {
332				return nil, err
333			}
334			if affected == 0 {
335				return nil, ErrInstanceNotFound
336			}
337		}
338	
339		updated := make([]Instance, 0, len(targets))
340		for _, target := range targets {
341			row := tx.QueryRow(`
342	SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
343	FROM service_instances
344	WHERE service_name = ? AND instance_id = ?`, serviceName, target.InstanceID)
345			instance, err := scanInstance(row)
346			if err == sql.ErrNoRows {
347				return nil, ErrInstanceNotFound
348			}
349			if err != nil {
350				return nil, err
351			}
352			updated = append(updated, instance)
353		}
354	
355		if err := tx.Commit(); err != nil {
356			return nil, err
357		}
358		return updated, nil
359	}
