497	func scanInstance(scanner rowScanner) (Instance, error) {
498		var instance Instance
499		var healthy int
500		var heartbeat string
501		if err := scanner.Scan(&instance.ServiceName, &instance.InstanceID, &instance.Address,
502			&instance.Port, &healthy, &instance.Weight, &heartbeat); err != nil {
503			return Instance{}, err
504		}
505		parsed, err := time.Parse(time.RFC3339Nano, heartbeat)
506		if err != nil {
507			return Instance{}, err
508		}
509		instance.Healthy = healthy != 0
510		instance.HeartbeatAt = parsed
511		return instance, nil
512	}
