833	// handleDiscover implements the weighted discovery entry: only explicitly
834	// healthy instances whose last heartbeat is not strictly past the lost
835	// boundary are returned. An instance exactly on the boundary is still
836	// online. Records strictly past the boundary are removed by the lost
837	// cleanup; online and unhealthy-but-fresh records are never touched.
838	func (s *Server) handleDiscover(c *gin.Context) {
839		bag, apiErr := buildParamBag(c)
840		if apiErr != nil {
841			writeError(c, apiErr)
842			return
843		}
844		serviceName, apiErr := bag.requiredText(serviceNameKeys, "service_name must not be empty")
845		if apiErr != nil {
846			writeError(c, apiErr)
847			return
848		}
849		evaluateValue, ok := bag.get(evaluateAtKeys)
850		if !ok {
851			writeError(c, errInvalidParameter("evaluate_at is required"))
852			return
853		}
854		evaluateAt, ok := parseTimeValue(evaluateValue)
855		if !ok {
856			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
857			return
858		}
859		timeoutValue, ok := bag.get(timeoutKeys)
860		if !ok {
861			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
862			return
863		}
864		timeout, ok := parseTimeout(timeoutValue)
865		if !ok || timeout <= 0 {
866			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
867			return
868		}
869	
870		instances, err := s.store.ListInstances(serviceName)
871		if err != nil {
872			writeError(c, errStorageUnavailable())
873			return
874		}
875		for _, instance := range instances {
876			if evaluateAt.Before(instance.HeartbeatAt) {
877				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
878				return
879			}
880		}
881		candidates := make([]gin.H, 0, len(instances))
882		lost := make([]store.Instance, 0)
883		for _, instance := range instances {
884			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
885				lost = append(lost, instance)
886				continue
887			}
888			if !instance.Healthy {
889				continue
890			}
891			candidates = append(candidates, instanceJSON(instance))
892		}
893		// Lost cleanup deletes records strictly past the timeout. It runs only
894		// after the request is fully validated, so a rejected query changes
895		// nothing.
896		for _, instance := range lost {
897			if _, err := s.store.DeleteInstance(instance.ServiceName, instance.InstanceID); err != nil {
898				writeError(c, errStorageUnavailable())
899				return
900			}
901		}
902		sortDiscoverHits(candidates)
903		c.JSON(200, gin.H{
904			"service_name":      serviceName,
905			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
906			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
907			"instances":         candidates,
908		})
909	}
