911	// handleBatchDiscover implements POST /api/v1/discover/batch. Several
912	// services share one evaluation point and timeout. Parameters and stored
913	// data are fully validated before any record is removed: every specified
914	// service is read first, the clock-skew guard covers every instance of
915	// every specified service, and lost records across all services are removed
916	// in one transaction so a failure never leaves partial deletions. Services
917	// that are not requested are never read or touched; a requested service
918	// without records yields an empty instance list while keeping its place in
919	// the request order.
920	func (s *Server) handleBatchDiscover(c *gin.Context) {
921		body, apiErr := readJSONObject(c)
922		if apiErr != nil {
923			writeError(c, apiErr)
924			return
925		}
926	
927		rawNames, present := body["service_names"]
928		if !present {
929			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
930			return
931		}
932		entries, ok := rawNames.([]any)
933		if !ok || len(entries) == 0 {
934			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
935			return
936		}
937		serviceNames := make([]string, 0, len(entries))
938		seen := make(map[string]struct{}, len(entries))
939		for _, rawName := range entries {
940			name, ok := rawName.(string)
941			if !ok {
942				writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
943				return
944			}
945			name = strings.TrimSpace(name)
946			if name == "" {
947				writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
948				return
949			}
950			if _, duplicated := seen[name]; duplicated {
951				writeError(c, errInvalidParameter("service_names must not contain duplicates"))
952				return
953			}
954			seen[name] = struct{}{}
955			serviceNames = append(serviceNames, name)
956		}
957	
958		evaluateValue, present := body["evaluate_at"]
959		if !present {
960			writeError(c, errInvalidParameter("evaluate_at is required"))
961			return
962		}
963		evaluateAt, ok := parseTimeValue(evaluateValue)
964		if !ok {
965			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
966			return
967		}
968		timeoutValue, present := body["heartbeat_timeout"]
969		if !present {
970			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
971			return
972		}
973		timeout, ok := parseTimeout(timeoutValue)
974		if !ok || timeout <= 0 {
975			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
976			return
977		}
978	
979		// Read every requested service before any classification or deletion,
980		// so a storage read failure changes nothing.
981		byService := make(map[string][]store.Instance, len(serviceNames))
982		for _, serviceName := range serviceNames {
983			instances, err := s.store.ListInstances(serviceName)
984			if err != nil {
985				writeError(c, errStorageUnavailable())
986				return
987			}
988			byService[serviceName] = instances
989		}
990		// The clock-skew guard covers all records before the lost boundary is
991		// applied, rejecting the whole batch without deleting anything.
992		for _, serviceName := range serviceNames {
993			for _, instance := range byService[serviceName] {
994				if evaluateAt.Before(instance.HeartbeatAt) {
995					writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
996					return
997				}
998			}
999		}
1000	
1001		lostKeys := make([]store.InstanceKey, 0)
1002		for _, serviceName := range serviceNames {
1003			for _, instance := range byService[serviceName] {
1004				if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1005					lostKeys = append(lostKeys, store.InstanceKey{
1006						ServiceName: instance.ServiceName,
1007						InstanceID:  instance.InstanceID,
1008					})
1009				}
1010			}
1011		}
1012		// All lost records are removed atomically across services.
1013		if len(lostKeys) > 0 {
1014			if err := s.store.DeleteInstances(lostKeys); err != nil {
1015				writeError(c, errStorageUnavailable())
1016				return
1017			}
1018		}
1019	
1020		services := make([]gin.H, 0, len(serviceNames))
1021		for _, serviceName := range serviceNames {
1022			candidates := make([]gin.H, 0)
1023			for _, instance := range byService[serviceName] {
1024				if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1025					continue
1026				}
1027				if !instance.Healthy {
1028					continue
1029				}
1030				candidates = append(candidates, instanceJSON(instance))
1031			}
1032			sortDiscoverHits(candidates)
1033			services = append(services, gin.H{
1034				"service_name": serviceName,
1035				"instances":    candidates,
1036			})
1037		}
1038		c.JSON(200, gin.H{
1039			"services":          services,
1040			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
1041			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
1042		})
1043	}
1044	
1045	// handleCleanup implements the standalone lost-instance cleanup entry. An
1046	// omitted service_name evaluates every service; an explicit service_name
1047	// must be non-empty and scopes the cleanup to that one service, leaving
1048	// every other service untouched. Only records strictly past the lost
1049	// boundary are deleted: records exactly on the boundary, still-online
1050	// records and unhealthy-but-fresh records are all kept. Every parameter is
1051	// validated before any deletion, and the deletion itself runs in one
1052	// transaction so a storage failure leaves no partial result.
1053	func (s *Server) handleCleanup(c *gin.Context) {
1054		bag, apiErr := buildParamBag(c)
1055		if apiErr != nil {
1056			writeError(c, apiErr)
1057			return
1058		}
1059	
1060		serviceName := ""
1061		scoped := false
1062		if value, present := bag.get(serviceNameKeys); present {
1063			serviceName = strings.TrimSpace(stringValue(value))
1064			if serviceName == "" {
1065				writeError(c, errInvalidParameter("service_name must not be empty"))
1066				return
1067			}
1068			scoped = true
1069		}
1070		evaluateValue, ok := bag.get(evaluateAtKeys)
1071		if !ok {
1072			writeError(c, errInvalidParameter("evaluate_at is required"))
1073			return
1074		}
1075		evaluateAt, ok := parseTimeValue(evaluateValue)
1076		if !ok {
1077			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
1078			return
1079		}
1080		timeoutValue, ok := bag.get(timeoutKeys)
1081		if !ok {
1082			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
1083			return
1084		}
1085		timeout, ok := parseTimeout(timeoutValue)
1086		if !ok || timeout <= 0 {
1087			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
1088			return
1089		}
1090	
1091		var instances []store.Instance
1092		var err error
1093		if scoped {
1094			instances, err = s.store.ListInstances(serviceName)
1095		} else {
1096			instances, err = s.store.ListAllInstances()
1097		}
1098		if err != nil {
1099			writeError(c, errStorageUnavailable())
1100			return
1101		}
1102		for _, instance := range instances {
1103			if evaluateAt.Before(instance.HeartbeatAt) {
1104				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
1105				return
1106			}
1107		}
1108	
1109		lost := make([]store.Instance, 0)
1110		keys := make([]store.InstanceKey, 0)
1111		for _, instance := range instances {
1112			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1113				lost = append(lost, instance)
1114				keys = append(keys, store.InstanceKey{
1115					ServiceName: instance.ServiceName,
1116					InstanceID:  instance.InstanceID,
1117				})
1118			}
1119		}
1120		if len(keys) > 0 {
1121			if err := s.store.DeleteInstances(keys); err != nil {
1122				writeError(c, errStorageUnavailable())
1123				return
1124			}
1125		}
1126	
1127		sort.SliceStable(lost, func(i, j int) bool {
1128			if lost[i].ServiceName != lost[j].ServiceName {
1129				return lost[i].ServiceName < lost[j].ServiceName
1130			}
1131			return lost[i].InstanceID < lost[j].InstanceID
1132		})
1133		removed := make([]gin.H, 0, len(lost))
1134		for _, instance := range lost {
1135			removed = append(removed, instanceJSON(instance))
1136		}
1137		c.JSON(200, gin.H{
1138			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
1139			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
1140			"removed":           len(removed),
1141			"instances":         removed,
1142		})
1143	}
1144	
1145	// sortDiscoverHits orders discovery hits by weight descending, then instance
1146	// id ascending, giving deterministic output for identical input.
1147	func sortDiscoverHits(instances []gin.H) {
1148		sort.SliceStable(instances, func(i, j int) bool {
1149			leftWeight, _ := toFloat(instances[i]["weight"])
1150			rightWeight, _ := toFloat(instances[j]["weight"])
1151			if leftWeight != rightWeight {
1152				return leftWeight > rightWeight
1153			}
1154			return stringValue(instances[i]["instance_id"]) < stringValue(instances[j]["instance_id"])
1155		})
1156	}
1157	
1158	// sortInstances orders by weight descending, heartbeat newest first, then
1159	// instance id ascending, giving deterministic output for identical input.
1160	func sortInstances(instances []gin.H) {
1161		sort.SliceStable(instances, func(i, j int) bool {
1162			left, right := instances[i], instances[j]
1163			leftWeight, _ := toFloat(left["weight"])
1164			rightWeight, _ := toFloat(right["weight"])
1165			if leftWeight != rightWeight {
1166				return leftWeight > rightWeight
1167			}
1168			leftHeartbeat, _ := parseTimeValue(left["heartbeat_at"])
1169			rightHeartbeat, _ := parseTimeValue(right["heartbeat_at"])
1170			if !leftHeartbeat.Equal(rightHeartbeat) {
1171				return leftHeartbeat.After(rightHeartbeat)
1172			}
1173			return stringValue(left["instance_id"]) < stringValue(right["instance_id"])
1174		})
1175	}
