58	func buildParamBag(c *gin.Context) (*paramBag, *apiError) {
59		bag := &paramBag{values: make(map[string]any)}
60	
61		for key, values := range c.Request.URL.Query() {
62			if len(values) > 0 {
63				bag.values[key] = values[0]
64			}
65		}
66	
67		if c.Request.Body != nil {
68			raw, err := io.ReadAll(c.Request.Body)
69			if err != nil {
70				return nil, errInvalidParameter("request body cannot be read")
71			}
72			if len(bytes.TrimSpace(raw)) > 0 {
73				var body map[string]any
74				if err := json.Unmarshal(raw, &body); err != nil {
75					return nil, errInvalidParameter("request body must be a JSON object")
76				}
77				for key, value := range body {
78					bag.values[key] = value
79				}
80			}
81		}
82	
83		for _, param := range c.Params {
84			bag.values[param.Key] = param.Value
85		}
86		return bag, nil
